import { useState } from 'react';
import { loadStripe } from '@stripe/stripe-js';
import { Elements, CardElement, useStripe, useElements } from '@stripe/react-stripe-js';
import { api } from '../api/client';

// Stripe publishable key
const stripePromise = loadStripe('pk_test_51TNkmZLaPu9ajsblOXkmm0uFNncVcq0FktYW0TLa7iTlgPmbS5nnK0LNTaAy4rHNOGeD6p3zCjGYS34RwcevFf8m00QQQa5hQE');

function OrderPaymentForm({ order, onClose, onSuccess, onError }) {
  const stripe = useStripe();
  const elements = useElements();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleSubmit = async (event) => {
    event.preventDefault();
    setLoading(true);
    setError(null);

    if (!stripe || !elements) {
      setLoading(false);
      return;
    }

    try {
      console.log('Creating payment intent for order:', order.id);

      // 1. Create payment intent with existing order ID
      const response = await api.post('/api/payments/create-payment-intent', {
        amount: Math.round((order.totalAmount || order.total) * 100), // Convert to cents
        currency: 'usd',
        orderId: order.id,
      });

      const { clientSecret, paymentIntentId } = response.data;
      console.log('Payment intent created:', { clientSecret, paymentIntentId });

      // 2. Confirm payment with Stripe
      const cardElement = elements.getElement(CardElement);
      const { error: paymentError, paymentIntent } = await stripe.confirmCardPayment(clientSecret, {
        payment_method: {
          card: cardElement,
          billing_details: {
            // You can collect billing details here if needed
          },
        },
      });

      if (paymentError) {
        console.error('Payment error:', paymentError);
        setError(paymentError.message);
        onError(paymentError);
      } else if (paymentIntent.status === 'succeeded') {
        console.log('Payment succeeded:', paymentIntent);

        // 3. Confirm payment with actual orderId
        await api.post('/api/payments/confirm', {
          paymentIntentId: paymentIntentId,
          orderId: order.id,
          status: 'COMPLETED',
        });

        console.log('Payment confirmed for order:', order.id);
        onSuccess(paymentIntent);
      }
    } catch (err) {
      console.error('Payment failed:', err);
      setError(err.message || 'Payment failed');
      onError(err);
    } finally {
      setLoading(false);
    }
  };

  const cardElementOptions = {
    style: {
      base: {
        fontSize: '16px',
        color: '#424770',
        '::placeholder': {
          color: '#aab7c4',
        },
      },
      invalid: {
        color: '#9e2146',
      },
    },
  };

  return (
    <div style={{
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      backgroundColor: 'rgba(0, 0, 0, 0.5)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      zIndex: 1000,
    }}>
      <div style={{
        backgroundColor: '#fff',
        borderRadius: '16px',
        padding: '32px',
        width: '90%',
        maxWidth: '500px',
        maxHeight: '90vh',
        overflowY: 'auto',
      }}>
        {/* Header */}
        <div style={{ marginBottom: '24px' }}>
          <h2 style={{ fontSize: '24px', fontWeight: '700', color: '#111827', margin: '0 0 8px 0' }}>
            Pay for Order
          </h2>
          <div style={{ fontSize: '14px', color: '#6b7280' }}>
            {order.restaurantName ?? `Order #${String(order.id).slice(-6).toUpperCase()}`}
          </div>
        </div>

        {/* Order Summary */}
        <div style={{
          backgroundColor: '#f9fafb',
          borderRadius: '12px',
          padding: '16px',
          marginBottom: '24px',
        }}>
          <div style={{ fontSize: '14px', color: '#6b7280', marginBottom: '8px' }}>Order Total</div>
          <div style={{ fontSize: '24px', fontWeight: '700', color: '#111827' }}>
            ${(order.totalAmount || order.total || 0).toFixed(2)}
          </div>
        </div>

        {/* Payment Form */}
        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '20px' }}>
            <label style={{ 
              display: 'block', 
              marginBottom: '8px', 
              fontSize: '14px', 
              fontWeight: '600',
              color: '#374151'
            }}>
              Card Details
            </label>
            <div style={{
              border: '1px solid #d1d5db',
              borderRadius: '8px',
              padding: '12px',
              backgroundColor: '#f9fafb'
            }}>
              <CardElement options={cardElementOptions} />
            </div>
          </div>

          {error && (
            <div style={{
              color: '#dc2626',
              fontSize: '14px',
              marginBottom: '16px',
              padding: '12px',
              backgroundColor: '#fef2f2',
              border: '1px solid #fecaca',
              borderRadius: '6px'
            }}>
              {error}
            </div>
          )}

          {/* Actions */}
          <div style={{ display: 'flex', gap: '12px' }}>
            <button
              type="button"
              onClick={onClose}
              disabled={loading}
              style={{
                flex: 1,
                padding: '12px 24px',
                borderRadius: '8px',
                border: '1px solid #d1d5db',
                backgroundColor: '#fff',
                color: '#374151',
                fontSize: '16px',
                fontWeight: '500',
                cursor: loading ? 'not-allowed' : 'pointer',
                opacity: loading ? 0.5 : 1,
              }}
            >
              Cancel
            </button>

            <button
              type="submit"
              disabled={!stripe || loading}
              style={{
                flex: 2,
                padding: '12px 24px',
                borderRadius: '8px',
                border: 'none',
                backgroundColor: loading ? '#9ca3af' : '#f97316',
                color: '#fff',
                fontSize: '16px',
                fontWeight: '600',
                cursor: (!stripe || loading) ? 'not-allowed' : 'pointer',
                opacity: (!stripe || loading) ? 0.5 : 1,
              }}
            >
              {loading ? 'Processing...' : `Pay $${(order.totalAmount || order.total || 0).toFixed(2)}`}
            </button>
          </div>
        </form>

        {/* Security Note */}
        <div style={{ 
          marginTop: '16px', 
          textAlign: 'center', 
          fontSize: '12px', 
          color: '#9ca3af' 
        }}>
          🔒 Secure payment powered by Stripe
        </div>
      </div>
    </div>
  );
}

export default function OrderPaymentModal({ order, onClose, onSuccess, onError }) {
  if (!order) return null;

  return (
    <Elements stripe={stripePromise}>
      <OrderPaymentForm 
        order={order}
        onClose={onClose}
        onSuccess={onSuccess}
        onError={onError}
      />
    </Elements>
  );
}
